    vals={k:s.Rational(v) for k,v in p.items()}
    if any(v.q!=1 for v in vals.values()):raise ValueError('Displayed input coefficients must be integers')
    a,b,c,d,u,v,e=[vals[k] for k in 'a b c d u v e'.split()]
